     1→// ==UserScript==
     2→// @name         Synapse Civitai Bridge
     3→// @namespace    synapse.civitai.bridge
     4→// @version      10.0.0
     5→// @description  Bridge for Synapse - Civitai API access via Meilisearch + tRPC
     6→// @author       SynapseTeam
     7→// @match        http://localhost:*/*
     8→// @match        http://127.0.0.1:*/*
     9→// @match        https://localhost:*/*
    10→// @connect      civitai.com
    11→// @connect      search-new.civitai.com
    12→// @grant        GM_xmlhttpRequest
    13→// @grant        GM_setValue
    14→// @grant        GM_getValue
    15→// @grant        unsafeWindow
    16→// @run-at       document-start
    17→// ==/UserScript==
    18→
    19→(function () {
    20→  'use strict';
    21→
    22→  // ==========================================================================
    23→  // Configuration
    24→  // ==========================================================================
    25→
    26→  const VERSION = '10.0.0';
    27→  const TRPC_BASE = 'https://civitai.com/api/trpc';
    28→  const MEILISEARCH_BASE = 'https://search-new.civitai.com';
    29→  const MEILISEARCH_TOKEN = '8c46eb2508e21db1e9828a97968d91ab1ca1caa5f70a00e88a2ba1e286603b61';
    30→  const MEILISEARCH_INDEX = 'models_v9';
    31→  const CACHE_TTL = 30000; // 30 seconds
    32→  const CACHE_MAX_SIZE = 200;
    33→  const DEFAULT_TIMEOUT = 15000; // 15 seconds (faster for Meilisearch)
    34→  const TRPC_TIMEOUT = 30000; // 30 seconds for tRPC
    35→  const IMAGE_FETCH_TIMEOUT = 60000; // 60 seconds for image.getInfinite which is VERY slow
    36→
    37→  // Target window (Firefox needs unsafeWindow)
    38→  const target = typeof unsafeWindow !== 'undefined' ? unsafeWindow : window;
    39→
    40→  // LRU Cache
    41→  const cache = new Map();
    42→
    43→  // ==========================================================================
    44→  // Configuration Storage
    45→  // ==========================================================================
    46→
    47→  function getConfig() {
    48→    return {
    49→      enabled: GM_getValue('synapse_bridge_enabled', true),
    50→      nsfw: GM_getValue('synapse_bridge_nsfw', true),
    51→    };
    52→  }
    53→
    54→  function saveConfig(updates) {
    55→    if (updates.enabled !== undefined) {
    56→      GM_setValue('synapse_bridge_enabled', updates.enabled);
    57→    }
    58→    if (updates.nsfw !== undefined) {
    59→      GM_setValue('synapse_bridge_nsfw', updates.nsfw);
    60→    }
    61→  }
    62→
    63→  // ==========================================================================
    64→  // LRU Cache
    65→  // ==========================================================================
    66→
    67→  function cacheGet(key) {
    68→    const item = cache.get(key);
    69→    if (!item) return null;
    70→
    71→    // Check TTL
    72→    if (Date.now() - item.ts > CACHE_TTL) {
    73→      cache.delete(key);
    74→      return null;
    75→    }
    76→
    77→    // LRU: move to end
    78→    cache.delete(key);
    79→    cache.set(key, item);
    80→    return item.data;
    81→  }
    82→
    83→  function cacheSet(key, data) {
    84→    // Evict oldest if full
    85→    if (cache.size >= CACHE_MAX_SIZE) {
    86→      const oldest = cache.keys().next().value;
    87→      cache.delete(oldest);
    88→    }
    89→    cache.set(key, { ts: Date.now(), data });
    90→  }
    91→
    92→  function cacheClear() {
    93→    cache.clear();
    94→  }
    95→
    96→  // ==========================================================================
    97→  // Meilisearch Request Builder (FAST search with query)
    98→  // ==========================================================================
    99→
   100→  function buildMeilisearchRequest(params, config) {
   101→    // Build NSFW filter based on config
   102→    // nsfwLevel: 1=None, 2=Soft, 4=Mature, 8=X, 16=Blocked, 32=???
   103→    let nsfwFilter = '';
   104→    if (config.nsfw) {
   105→      // All content
   106→      nsfwFilter = '(nsfwLevel=1 OR nsfwLevel=2 OR nsfwLevel=4 OR nsfwLevel=8 OR nsfwLevel=16)';
   107→    } else {
   108→      // SFW only
   109→      nsfwFilter = '(nsfwLevel=1 OR nsfwLevel=2)';
   110→    }
   111→
   112→    // Build additional filters
   113→    const filters = [nsfwFilter];
   114→
   115→    // Type filter
   116→    if (params.filters?.types) {
   117→      const types = Array.isArray(params.filters.types)
   118→        ? params.filters.types
   119→        : [params.filters.types];
   120→      if (types.length > 0) {
   121→        filters.push(`(type IN [${types.map((t) => `'${t}'`).join(', ')}])`);
   122→      }
   123→    }
   124→
   125→    // Base model filter
   126→    if (params.filters?.baseModel) {
   127→      const baseModels = Array.isArray(params.filters.baseModel)
   128→        ? params.filters.baseModel
   129→        : [params.filters.baseModel];
   130→      if (baseModels.length > 0) {
   131→        filters.push(
   132→          `(version.baseModel IN [${baseModels.map((b) => `'${b}'`).join(', ')}])`
   133→        );
   134→      }
   135→    }
   136→
   137→    // Sort mapping: Meilisearch uses different sort syntax
   138→    // For now, we'll use default relevance sort when searching
   139→    // tRPC is better for sorted browsing without query
   140→
   141→    return {
   142→      queries: [
   143→        {
   144→          q: params.q || '',
   145→          indexUid: MEILISEARCH_INDEX,
   146→          facets: [
   147→            'category.name',
   148→            'checkpointType',
   149→            'fileFormats',
   150→            'tags.name',
   151→            'type',
   152→            'user.username',
   153→            'version.baseModel',
   154→          ],
   155→          attributesToHighlight: [],
   156→          highlightPreTag: '__ais-highlight__',
   157→          highlightPostTag: '__/ais-highlight__',
   158→          limit: params.limit || 20,
   159→          offset: params.offset || 0,
   160→          filter: filters,
   161→        },
   162→      ],
   163→    };
   164→  }
   165→
   166→  // ==========================================================================
   167→  // tRPC URL Builders (for browse without query, model detail)
   168→  // ==========================================================================
   169→
   170→  function buildSearchUrl(params, config) {
   171→    const input = {
   172→      json: {
   173→        query: params.q || undefined,
   174→        limit: params.limit || 20,
   175→        cursor: params.cursor || undefined,
   176→        sort: params.sort || 'Most Downloaded',
   177→        period: params.period || 'AllTime',
   178→        // browsingLevel: 31 = all content, 1 = SFW only
   179→        browsingLevel: config.nsfw ? 31 : 1,
   180→        // Optional filters
   181→        types: params.filters?.types ? [params.filters.types] : undefined,
   182→        baseModels: params.filters?.baseModel
   183→          ? [params.filters.baseModel]
   184→          : undefined,
   185→      },
   186→    };
   187→
   188→    // Clean undefined values
   189→    Object.keys(input.json).forEach((k) => {
   190→      if (input.json[k] === undefined) delete input.json[k];
   191→    });
   192→
   193→    return `${TRPC_BASE}/model.getAll?input=${encodeURIComponent(
   194→      JSON.stringify(input)
   195→    )}`;
   196→  }
   197→
   198→  function buildModelUrl(modelId) {
   199→    const input = { json: { id: modelId } };
   200→    return `${TRPC_BASE}/model.getById?input=${encodeURIComponent(
   201→      JSON.stringify(input)
   202→    )}`;
   203→  }
   204→
   205→  function buildModelImagesUrl(modelId, config, limit = 50) {
   206→    const input = {
   207→      json: {
   208→        modelId: modelId,
   209→        limit: limit,
   210→        sort: 'Most Reactions',
   211→        period: 'AllTime',
   212→        // browsingLevel: 31 = all content, 1 = SFW only
   213→        browsingLevel: config.nsfw ? 31 : 1,
   214→      },
   215→    };
   216→    return `${TRPC_BASE}/image.getInfinite?input=${encodeURIComponent(
   217→      JSON.stringify(input)
   218→    )}`;
   219→  }
