   221→  // ==========================================================================
   222→  // Meilisearch Request Handler (POST with JSON body)
   223→  // ==========================================================================
   224→
   225→  async function meilisearchRequest(body, opts = {}) {
   226→    const cacheKey = `meili:${JSON.stringify(body)}`;
   227→
   228→    // Check cache first (unless noCache)
   229→    if (!opts.noCache) {
   230→      const cached = cacheGet(cacheKey);
   231→      if (cached) {
   232→        return {
   233→          ok: true,
   234→          data: cached,
   235→          meta: { cached: true, durationMs: 0, source: 'meilisearch' },
   236→        };
   237→      }
   238→    }
   239→
   240→    const startTime = Date.now();
   241→
   242→    return new Promise((resolve) => {
   243→      let resolved = false;
   244→
   245→      const finish = (result) => {
   246→        if (!resolved) {
   247→          resolved = true;
   248→          resolve(result);
   249→        }
   250→      };
   251→
   252→      const request = GM_xmlhttpRequest({
   253→        method: 'POST',
   254→        url: `${MEILISEARCH_BASE}/multi-search`,
   255→        headers: {
   256→          'Content-Type': 'application/json',
   257→          Accept: 'application/json',
   258→          Authorization: `Bearer ${MEILISEARCH_TOKEN}`,
   259→          'X-Meilisearch-Client':
   260→            'Meilisearch instant-meilisearch (v0.13.5) ; Meilisearch JavaScript (v0.34.0)',
   261→        },
   262→        data: JSON.stringify(body),
   263→        timeout: opts.timeout || DEFAULT_TIMEOUT,
   264→        responseType: 'json',
   265→
   266→        onload: (response) => {
   267→          if (response.status >= 200 && response.status < 300) {
   268→            try {
   269→              let data = response.response;
   270→
   271→              // Parse if string
   272→              if (!data && response.responseText) {
   273→                data = JSON.parse(response.responseText);
   274→              }
   275→
   276→              // Meilisearch returns { results: [{ hits: [...], ... }] }
   277→              const result = data?.results?.[0] || data;
   278→
   279→              cacheSet(cacheKey, result);
   280→
   281→              finish({
   282→                ok: true,
   283→                data: result,
   284→                meta: {
   285→                  cached: false,
   286→                  durationMs: Date.now() - startTime,
   287→                  source: 'meilisearch',
   288→                },
   289→              });
   290→            } catch (e) {
   291→              finish({
   292→                ok: false,
   293→                error: {
   294→                  code: 'PARSE_ERROR',
   295→                  message: e.message,
   296→                },
   297→              });
   298→            }
   299→          } else {
   300→            const isRetryable =
   301→              response.status === 429 || response.status >= 500;
   302→
   303→            finish({
   304→              ok: false,
   305→              error: {
   306→                code: response.status === 429 ? 'RATE_LIMIT' : 'HTTP_ERROR',
   307→                message: `HTTP ${response.status}`,
   308→                httpStatus: response.status,
   309→                retryable: isRetryable,
   310→              },
   311→            });
   312→          }
   313→        },
   314→
   315→        onerror: () => {
   316→          finish({
   317→            ok: false,
   318→            error: {
   319→              code: 'NETWORK',
   320→              message: 'Network error - check connection',
   321→            },
   322→          });
   323→        },
   324→
   325→        ontimeout: () => {
   326→          finish({
   327→            ok: false,
   328→            error: {
   329→              code: 'TIMEOUT',
   330→              message: 'Request timed out',
   331→              retryable: true,
   332→            },
   333→          });
   334→        },
   335→      });
   336→
   337→      // Abort signal support
   338→      if (opts.signal) {
   339→        opts.signal.addEventListener('abort', () => {
   340→          try {
   341→            request.abort?.();
   342→          } catch (e) {
   343→            // Ignore abort errors
   344→          }
   345→          finish({
   346→            ok: false,
   347→            error: {
   348→              code: 'ABORTED',
   349→              message: 'Request cancelled',
   350→            },
   351→          });
   352→        });
   353→      }
   354→    });
   355→  }
   356→
   357→  // ==========================================================================
   358→  // tRPC Request Handler (GET requests)
   359→  // ==========================================================================
   360→
   361→  async function trpcRequest(url, opts = {}) {
   362→    const cacheKey = url;
   363→
   364→    // Check cache first (unless noCache)
   365→    if (!opts.noCache) {
   366→      const cached = cacheGet(cacheKey);
   367→      if (cached) {
   368→        return {
   369→          ok: true,
   370→          data: cached,
   371→          meta: { cached: true, durationMs: 0, source: 'trpc' },
   372→        };
   373→      }
   374→    }
   375→
   376→    const startTime = Date.now();
   377→
   378→    return new Promise((resolve) => {
   379→      let resolved = false;
   380→
   381→      const finish = (result) => {
   382→        if (!resolved) {
   383→          resolved = true;
   384→          resolve(result);
   385→        }
   386→      };
   387→
   388→      const request = GM_xmlhttpRequest({
   389→        method: 'GET',
   390→        url,
   391→        headers: {
   392→          'Content-Type': 'application/json',
   393→          Accept: 'application/json',
   394→        },
   395→        timeout: opts.timeout || TRPC_TIMEOUT,
   396→        responseType: 'json',
   397→
   398→        onload: (response) => {
   399→          if (response.status >= 200 && response.status < 300) {
   400→            try {
   401→              let data = response.response;
   402→
   403→              // Parse if string
   404→              if (!data && response.responseText) {
   405→                data = JSON.parse(response.responseText);
   406→              }
   407→
   408→              // tRPC wraps response in result.data.json
   409→              const result = data?.result?.data?.json || data;
   410→
   411→              cacheSet(cacheKey, result);
   412→
   413→              finish({
   414→                ok: true,
   415→                data: result,
   416→                meta: {
   417→                  cached: false,
   418→                  durationMs: Date.now() - startTime,
   419→                  source: 'trpc',
   420→                },
   421→              });
   422→            } catch (e) {
   423→              finish({
   424→                ok: false,
   425→                error: {
   426→                  code: 'PARSE_ERROR',
   427→                  message: e.message,
   428→                },
   429→              });
   430→            }
   431→          } else {
   432→            const isRetryable =
   433→              response.status === 429 || response.status >= 500;
   434→
   435→            finish({
   436→              ok: false,
   437→              error: {
   438→                code: response.status === 429 ? 'RATE_LIMIT' : 'HTTP_ERROR',
   439→                message: `HTTP ${response.status}`,
   440→                httpStatus: response.status,
   441→                retryable: isRetryable,
   442→              },
   443→            });
   444→          }
   445→        },
   446→
   447→        onerror: () => {
   448→          finish({
   449→            ok: false,
   450→            error: {
   451→              code: 'NETWORK',
   452→              message: 'Network error - check connection',
   453→            },
   454→          });
   455→        },
   456→
   457→        ontimeout: () => {
   458→          finish({
   459→            ok: false,
   460→            error: {
   461→              code: 'TIMEOUT',
   462→              message: 'Request timed out',
   463→              retryable: true,
   464→            },
   465→          });
   466→        },
   467→      });
   468→
   469→      // Abort signal support
   470→      if (opts.signal) {
   471→        opts.signal.addEventListener('abort', () => {
   472→          try {
   473→            request.abort?.();
   474→          } catch (e) {
   475→            // Ignore abort errors
   476→          }
   477→          finish({
   478→            ok: false,
   479→            error: {
   480→              code: 'ABORTED',
   481→              message: 'Request cancelled',
   482→            },
   483→          });
   484→        });
   485→      }
   486→    });
   487→  }
