   489→  // ==========================================================================
   490→  // Bridge API
   491→  // ==========================================================================
   492→
   493→  const bridge = {
   494→    version: VERSION,
   495→
   496→    /**
   497→     * Check if bridge is enabled
   498→     */
   499→    isEnabled: () => getConfig().enabled,
   500→
   501→    /**
   502→     * Get current status
   503→     */
   504→    getStatus: () => {
   505→      const config = getConfig();
   506→      return {
   507→        enabled: config.enabled,
   508→        nsfw: config.nsfw,
   509→        version: VERSION,
   510→        cacheSize: cache.size,
   511→        features: ['meilisearch', 'trpc', 'hybrid'],
   512→      };
   513→    },
   514→
   515→    /**
   516→     * Update configuration
   517→     */
   518→    configure: (updates) => {
   519→      saveConfig(updates);
   520→      return bridge.getStatus();
   521→    },
   522→
   523→    /**
   524→     * Clear cache
   525→     */
   526→    clearCache: () => {
   527→      const prevSize = cache.size;
   528→      cacheClear();
   529→      return { cleared: true, previousSize: prevSize };
   530→    },
   531→
   532→    /**
   533→     * HYBRID SEARCH - Uses Meilisearch for queries, tRPC for browse
   534→     *
   535→     * Strategy:
   536→     * - If query provided (q) → Use Meilisearch (FAST full-text search)
   537→     * - If no query (browse) → Use tRPC model.getAll (better sorting/filtering)
   538→     *
   539→     * @param {Object} params - Search parameters
   540→     * @param {string} params.q - Search query (triggers Meilisearch)
   541→     * @param {number} params.limit - Results limit (default: 20)
   542→     * @param {string} params.sort - Sort order (tRPC only)
   543→     * @param {string} params.period - Time period filter (tRPC only)
   544→     * @param {string} params.cursor - Pagination cursor (tRPC only)
   545→     * @param {number} params.offset - Pagination offset (Meilisearch only)
   546→     * @param {Object} params.filters - Additional filters
   547→     * @param {Object} opts - Request options
   548→     * @param {AbortSignal} opts.signal - Abort signal
   549→     * @param {boolean} opts.noCache - Skip cache
   550→     * @param {boolean} opts.forceTrpc - Force tRPC even with query
   551→     */
   552→    search: async (params, opts = {}) => {
   553→      const config = getConfig();
   554→
   555→      if (!config.enabled) {
   556→        return {
   557→          ok: false,
   558→          error: {
   559→            code: 'DISABLED',
   560→            message: 'Bridge is disabled',
   561→          },
   562→        };
   563→      }
   564→
   565→      // HYBRID STRATEGY:
   566→      // - Query search → Meilisearch (fast full-text)
   567→      // - Browse (no query) → tRPC (sorting, pagination)
   568→      const hasQuery = params.q && params.q.trim().length > 0;
   569→      const useMeilisearch = hasQuery && !opts.forceTrpc;
   570→
   571→      if (useMeilisearch) {
   572→        // Use Meilisearch for query search
   573→        const body = buildMeilisearchRequest(params, config);
   574→        const result = await meilisearchRequest(body, opts);
   575→
   576→        if (!result.ok) return result;
   577→
   578→        // Transform Meilisearch response to match expected format
   579→        const hits = result.data?.hits || [];
   580→        return {
   581→          ok: true,
   582→          data: {
   583→            items: hits,
   584→            // Meilisearch uses offset/limit, not cursor
   585→            nextCursor: undefined,
   586→            // Estimate if more results
   587→            hasMore: hits.length >= (params.limit || 20),
   588→            totalHits: result.data?.estimatedTotalHits || hits.length,
   589→          },
   590→          meta: {
   591→            ...result.meta,
   592→            source: 'meilisearch',
   593→            query: params.q,
   594→          },
   595→        };
   596→      } else {
   597→        // Use tRPC for browse without query
   598→        const url = buildSearchUrl(params, config);
   599→        const result = await trpcRequest(url, opts);
   600→
   601→        if (!result.ok) return result;
   602→
   603→        return {
   604→          ok: true,
   605→          data: {
   606→            items: result.data?.items || [],
   607→            nextCursor: result.data?.nextCursor,
   608→            hasMore: !!result.data?.nextCursor,
   609→          },
   610→          meta: {
   611→            ...result.meta,
   612→            source: 'trpc',
   613→          },
   614→        };
   615→      }
   616→    },
   617→
   618→    /**
   619→     * Direct Meilisearch search (bypass hybrid logic)
   620→     *
   621→     * @param {Object} params - Search parameters
   622→     * @param {Object} opts - Request options
   623→     */
   624→    searchMeilisearch: async (params, opts = {}) => {
   625→      const config = getConfig();
   626→
   627→      if (!config.enabled) {
   628→        return {
   629→          ok: false,
   630→          error: {
   631→            code: 'DISABLED',
   632→            message: 'Bridge is disabled',
   633→          },
   634→        };
   635→      }
   636→
   637→      const body = buildMeilisearchRequest(params, config);
   638→      return meilisearchRequest(body, opts);
   639→    },
   640→
   641→    /**
   642→     * Direct tRPC search (bypass hybrid logic)
   643→     *
   644→     * @param {Object} params - Search parameters
   645→     * @param {Object} opts - Request options
   646→     */
   647→    searchTrpc: async (params, opts = {}) => {
   648→      const config = getConfig();
   649→
   650→      if (!config.enabled) {
   651→        return {
   652→          ok: false,
   653→          error: {
   654→            code: 'DISABLED',
   655→            message: 'Bridge is disabled',
   656→          },
   657→        };
   658→      }
   659→
   660→      const url = buildSearchUrl(params, config);
   661→      return trpcRequest(url, opts);
   662→    },
   663→
   664→    /**
   665→     * Get model details via tRPC
   666→     *
   667→     * @param {number} modelId - Model ID
   668→     * @param {Object} opts - Request options
   669→     */
   670→    getModel: async (modelId, opts = {}) => {
   671→      const config = getConfig();
   672→
   673→      if (!config.enabled) {
   674→        return {
   675→          ok: false,
   676→          error: {
   677→            code: 'DISABLED',
   678→            message: 'Bridge is disabled',
   679→          },
   680→        };
   681→      }
   682→
   683→      const url = buildModelUrl(modelId);
   684→      return trpcRequest(url, opts);
   685→    },
   686→
   687→    /**
   688→     * Get images for a model via tRPC image.getInfinite
   689→     *
   690→     * NOTE: model.getById only returns post IDs, not actual images!
   691→     * This method fetches the images separately.
   692→     *
   693→     * @param {number} modelId - Model ID
   694→     * @param {Object} opts - Request options
   695→     * @param {number} opts.limit - Max images to fetch (default: 50)
   696→     */
   697→    getModelImages: async (modelId, opts = {}) => {
